import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")

    system = platform.system()
    if system == "Windows":
        command = ["wmic", "cpu", "get", "loadpercentage"]
    else:
        command = ["bash", "-c", "top -bn1 | grep 'Cpu(s)' | awk '{print $2}'"]

    records = []
    end_time = time.time() + duration

    while time.time() < end_time:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
        try:
            result = subprocess.check_output(command, stderr=subprocess.DEVNULL).decode().strip()
            cpu_usage = float(result.split()[-1]) if system != "Windows" else float(result.split("\n")[1])
            records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        except Exception:
            continue
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w") as logfile:
            json.dump(records, logfile)
        return LOGFILE_PATH
    except IOError:
        return None

