import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    command = ['wmic', 'cpu', 'get', 'loadpercentage'] if platform.system() == 'Windows' else ['top', '-bn1']
    data = []
    iterations = int(duration / interval)
    for _ in range(iterations):
        timestamp = time.time()
        try:
            output = subprocess.check_output(command, stderr=subprocess.DEVNULL)
            if platform.system() == 'Windows':
                usage = int(output.decode().splitlines()[1].strip())
            else:
                usage = 100 - int(output.decode().split()[-1].replace('%', ''))
            data.append({"timestamp": timestamp, "cpu_usage": usage})
        except Exception:
            pass
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as logfile:
            json.dump(data, logfile)
        return LOGFILE_PATH
    except IOError:
        return None

