import subprocess
import time
import threading
def task_func(file_list):
    results = []
    def run_process(file):
        try:
            process = subprocess.run([file], shell=True)
            results.append(process.returncode)
        except Exception:
            results.append(-1)
    threads = []
    for file in file_list:
        thread = threading.Thread(target=run_process, args=(file,))
        threads.append(thread)
        thread.start()
    for thread in threads:
        thread.join()
    return results

